import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, d, w = data[0], data[1], data[2]
    p = data[3:3 + n]

    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + p[i]

    m = n - d + 1
    q = [0] * m
    for i in range(m):
        q[i] = pref[i + d] - pref[i]

    def possible(k):
        dq = deque()
        init_right = k - d

        for i in range(init_right + 1):
            v = q[i]
            while dq and q[dq[-1]] <= v:
                dq.pop()
            dq.append(i)

        for left in range(n - k + 1):
            while dq[0] < left:
                dq.popleft()

            max_free = q[dq[0]]
            total = pref[left + k] - pref[left]

            if total - max_free <= w:
                return True

            nxt = left + k - d + 1
            if nxt < m:
                v = q[nxt]
                while dq and q[dq[-1]] <= v:
                    dq.pop()
                dq.append(nxt)

        return False

    lo, hi = d, n
    ans = d

    while lo <= hi:
        mid = (lo + hi) // 2
        if possible(mid):
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1

    print(ans)


